    const shape=new T.Shape(), outer=0.5, inner=0.22, points=5;
    for(let i=0;i<points*2;i++){const r=i%2===0?outer:inner,a=i*Math.PI/points-Math.PI/2,x=Math.cos(a)*r,y=Math.sin(a)*r;if(i===0)shape.moveTo(x,y);else shape.lineTo(x,y);} const geo=new T.ExtrudeGeometry(shape,{depth:0.2,bevelEnabled:true,bevelSegments:2,steps:1,bevelSize:0.04,bevelThickness:0.05}); geo.center();
