  function sun2(){const g=new T.Group(),sun=new T.Mesh(new T.SphereGeometry(2.05,32,32),new T.MeshStandardMaterial({color:0xffdd4c,emissive:0xff9f00,emissiveIntensity:1.25,roughness:0.4,metalness:0.02}));g.add(sun);for(let i=0;i<16;i++){const ray=new T.Mesh(new T.ConeGeometry(0.16,1+rand(20+i)*0.5,8),new T.MeshStandardMaterial({color:0xffe173,emissive:0xffe173,emissiveIntensity:0.8,transparent:true,opacity:0.95}));const phi=Math.acos(2*(i/16)-1),theta=i*Math.PI*(3-Math.sqrt(5));ray.position.setFromSphericalCoords(2.75,phi,theta);ray.lookAt(0,0,0);ray.rotateX(Math.PI/2);g.add(ray);}g.userData.special='sun2';return g;}
