  function galaxy2(variant,seed){const g=new T.Group(),sets={0:[0x66c4ff,0x8b6cff,0xffffff],1:[0xff8dcf,0x855dff,0xfff1a8]},[c1,c2,c3]=sets[variant],positions=[],colors=[],color=new T.Color(),arms=2+(variant%2),ppa=180;for(let arm=0;arm<arms;arm++){for(let i=0;i<ppa;i++){const t=i/ppa,a=t*Math.PI*4.4+arm*Math.PI*2/arms,r=0.3+t*3,tw=r*0.55,x=Math.cos(a+tw)*r+(rand(seed+i+arm*10)-0.5)*0.25,y=(rand(seed+i*2+arm*30)-0.5)*0.8*(1-t)+(rand(seed+i*7)-0.5)*0.18,z=Math.sin(a+tw)*r+(rand(seed+i*3+arm*70)-0.5)*0.25;positions.push(x,y,z);color.set(t<0.33?c3:t<0.66?c1:c2);colors.push(color.r,color.g,color.b);}}for(let i=0;i<100;i++){const r=rand(seed+500+i)*0.8,theta=rand(seed+600+i)*Math.PI*2,phi=rand(seed+700+i)*Math.PI;positions.push(Math.sin(phi)*Math.cos(theta)*r,(rand(seed+800+i)-0.5)*0.5,Math.sin(phi)*Math.sin(theta)*r);color.set(c3);colors.push(color.r,color.g,color.b);}const geom=new T.BufferGeometry();geom.setAttribute('position',new T.Float32BufferAttribute(positions,3));geom.setAttribute('color',new T.Float32BufferAttribute(colors,3));const pts=new T.Points(geom,new T.PointsMaterial({size:0.12,vertexColors:true,transparent:true,opacity:0.95,depthWrite:false}));pts.rotation.x=0.45;g.add(pts);g.userData.special='galaxy';return g;}

